function blockMessage(form: FormState): string {
  if (!form.maKh.trim()) return 'Bạn chưa nhập mã đối tượng';
  if (!form.maNx.trim()) return 'Bạn chưa nhập tài khoản nợ ';
  if (!form.tkThueNo.trim()) return 'Bạn chưa nhập tài khoản thuế nợ ';
  if (!form.tkThueCo.trim()) return 'Bạn chưa nhập tài khoản thuế có ';
  for (const line of form.lines) {
    if (!line.maKhoI.trim()) return 'Bạn chưa nhập kho xuất ';
    if (!line.tkVt.trim()) return 'Bạn chưa nhập tài khoản kho ';
  }
  return '';
}

function toWrite(form: FormState, mode: 'create' | 'copy' | 'edit'): PxfSupplierReturnWrite {
  const lines: PxfSupplierReturnWriteLine[] = form.lines.map(line => {
    const row: PxfSupplierReturnWriteLine = {
      maVt: textOrNull(line.maVt),
      maVitri: textOrNull(line.maVitri),
      maKhoI: textOrNull(line.maKhoI),
      ton13: num(line.ton13),
      soLuong: num(line.soLuong),
      giaNt: num(line.giaNt),
      tienNt: num(line.tienNt),
      tkVt: textOrNull(line.tkVt),
      gia: num(line.gia),
      tien: num(line.tien),
      maVvI: textOrNull(line.maVvI),
      maHdI: textOrNull(line.maHdI),
      maPhiI: textOrNull(line.maPhiI),
      maTtlnI: textOrNull(line.maTtlnI),
      maTtcpI: textOrNull(line.maTtcpI),
      maBpI: textOrNull(line.maBpI),
    };
    if (mode === 'edit' && line.sttRec0.trim()) row.sttRec0 = line.sttRec0.trim();
    return row;
  });
  return {
    maCt: 'PXF',
    maGd: form.maGd,
    maPost: form.maPost,
    maQuyen: textOrNull(form.maQuyen),
    ngayCt: dateOrNull(form.ngayCt),
    ngayLct: dateOrNull(form.ngayLct),
    soCt: textOrNull(form.soCt),
    soSeri: textOrNull(form.soSeri),
    soLo: textOrNull(form.soLo),
    ngayLo: dateOrNull(form.ngayLo),
    maKh: textOrNull(form.maKh),
    ongBa: textOrNull(form.ongBa),
    diaChi: textOrNull(form.diaChi),
    maSoThue: textOrNull(form.maSoThue),
    dienGiai: textOrNull(form.dienGiai),
    tenKhVat: textOrNull(form.tenKhVat),
    diaChiVat: textOrNull(form.diaChiVat),
    tenVtThue: textOrNull(form.tenVtThue),
    maBpH: textOrNull(form.maBpH),
    maHsH: textOrNull(form.maHsH),
    maNx: textOrNull(form.maNx),
    pxGiaDd: form.pxGiaDd ? 1 : 0,
    maNt: textOrNull(form.maNt),
    tyGia: num(form.tyGia),
    mauHd: textOrNull(form.mauHd),
    mauSo: textOrNull(form.mauSo),
    mauBc: textOrNull(form.mauBc),
    suaThue: form.suaThue ? 1 : 0,
    eThue: form.eThue ? 1 : 0,
    maThue: textOrNull(form.maThue),
    thueSuat: num(form.thueSuat),
    tkThueNo: textOrNull(form.tkThueNo),
    tkThueCo: textOrNull(form.tkThueCo),
    hanTt: num(form.hanTt),
    lenhSo: textOrNull(form.lenhSo),
    lenhPo: textOrNull(form.lenhPo),
    lenhRo: textOrNull(form.lenhRo),
    lenhVt: textOrNull(form.lenhVt),
    ghiChu: textOrNull(form.ghiChu),
    tSoLuong: form.tSoLuong,
    tSoluong1: form.tSoluong1,
    tTienNt: form.tTienNt,
    tTien: form.tTien,
    tThueNt: form.tThueNt,
    tThue: form.tThue,
    tTtNt: form.tTtNt,
    tTt: form.tTt,
    lines,
  };
}

const PxfFormPage: React.FC = () => {
  const navigate = useInAppNavigate();
  const dispatch = useAppDispatch();
  const { sttRec } = useParams();
  const [searchParams] = useSearchParams();
  const mode = searchParams.get('mode');
  const copyFrom = searchParams.get('copyFrom') ?? '';
  const isView = Boolean(sttRec) && mode === 'view';
  const isCopy = !sttRec && copyFrom.length > 0;
  const isNew = !sttRec;
  const readOnly = isView;
  const [form, setForm] = useState<FormState>(emptyForm);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [missing, setMissing] = useState(false);
  const [selectedLine, setSelectedLine] = useState(-1);
  const { onDirtyChange, guardedNavigate, leaveConfirmModalProps } = useFormLeaveGuard({ message: LEAVE_MESSAGE });
  const { markDirty, markClean } = useDirtyTracking(isView ? undefined : onDirtyChange);

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      if (!sttRec && !copyFrom) {
        setForm(emptyForm());
        setMissing(false);
        setError('');
        markClean();
        return;
      }
      setLoading(true);
      setError('');
      setMissing(false);
      try {
        const dto = await getPxfSupplierReturn(sttRec || copyFrom);
        if (cancelled) return;
        setForm(formFromApi(dto, isCopy));
        markClean();
      } catch (err) {
        if (cancelled) return;
        setMissing(true);
        setError(err instanceof Error ? err.message : getApiErrorMessage(err, 'Không tìm thấy phiếu xuất trả lại nhà cung cấp'));
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    void load();
    return () => {
      cancelled = true;
    };
  }, [sttRec, copyFrom, isCopy, markClean]);

  const touch = (next: FormState) => {
    setForm(next);
    if (!readOnly) markDirty();
  };

  const setField = <K extends keyof FormState>(key: K, value: FormState[K]) => {
    touch({ ...form, [key]: value });
  };

  const setLine = (index: number, patch: Partial<LineState>) => {
    const lines = form.lines.map((line, i) => (i === index ? { ...line, ...patch } : line));
    touch({ ...form, lines });
  };

  const onBlurCustomer = async () => {
    const code = form.maKh.trim();
    if (!code) {
      setForm(prev => ({ ...prev, tenKh: '' }));
      return;
    }
    try {
      const res = await ktService.searchCustomers({ search: code, page: 1, pageSize: 20, isActive: true });
      const hit = res.items.find(item => item.code.trim().toLowerCase() === code.toLowerCase());
      setForm(prev => ({ ...prev, tenKh: hit?.name ?? '' }));
    } catch {
      /* tra cứu không chặn gõ */
    }
  };

  const onBlurAccount = async () => {
    const code = form.maNx.trim();
    if (!code) {
      setForm(prev => ({ ...prev, tenNx: '' }));
      return;
    }
    try {
      const res = await ktService.searchAccounts({ search: code, page: 1, pageSize: 20, isActive: true });
      const hit = res.items.find(item => item.code.trim().toLowerCase() === code.toLowerCase());
      setForm(prev => ({ ...prev, tenNx: hit?.name ?? '' }));
    } catch {
      /* tra cứu không chặn gõ */
    }
  };

  const onBlurMaterial = async (index: number) => {
    const code = form.lines[index]?.maVt.trim() ?? '';
    if (!code) {
      setForm(prev => ({
        ...prev,
        lines: prev.lines.map((line, i) => (i === index ? { ...line, tenVt: '', dvt: '' } : line)),
      }));
      return;
    }
    try {
      const res = await ktService.searchMaterials({ search: code, page: 1, pageSize: 20 });
      const hit = res.items.find(item => item.code.trim().toLowerCase() === code.toLowerCase());
      setForm(prev => ({
        ...prev,
        lines: prev.lines.map((line, i) => (i === index
          ? { ...line, tenVt: hit?.name ?? '', dvt: hit?.unitCode ?? '' }
          : line)),
      }));
    } catch {
      /* tra cứu không chặn gõ */
    }
  };

  const onSave = async () => {
    const blocked = blockMessage(form);
    if (blocked) {
      setError(blocked);
      dispatchAppToast(dispatch, { type: 'error', message: blocked });
      return;
    }
    setSaving(true);
    setError('');
    try {
      const writeMode = isCopy ? 'copy' : isNew ? 'create' : 'edit';
      const body = toWrite(form, writeMode);
      const saved = isNew
        ? await createPxfSupplierReturn(body)
        : await updatePxfSupplierReturn(sttRec ?? '', body);
      markClean();
      dispatchAppToast(dispatch, { type: 'success', message: 'Đã lưu phiếu xuất trả lại nhà cung cấp' });
      navigate(`/kt/pxf/${saved.sttRec}`);
      if (!isNew) {
        const fresh = await getPxfSupplierReturn(saved.sttRec);
        setForm(formFromApi(fresh, false));
        markClean();
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : getApiErrorMessage(err, 'Lưu thất bại');
      setError(message);
      dispatchAppToast(dispatch, { type: 'error', message });
    } finally {
      setSaving(false);
    }
  };

  const title = isView
    ? 'Xem phiếu xuất trả lại nhà cung cấp'
    : isNew
      ? 'Thêm phiếu xuất trả lại nhà cung cấp'
      : 'Sửa phiếu xuất trả lại nhà cung cấp';

  return (
    <div className={df.page} data-testid="ct-pxf-form">
      <DocumentFormHeader
        title={title}
        isNew={isNew}
        isReadOnly={readOnly}
        saving={saving}
        testIdPrefix="ct-pxf"
        saveLabel="Lưu"
        saveEditLabel="Lưu"
        onBack={() => guardedNavigate(() => navigate('/kt/pxf'))}
        onSave={missing || readOnly ? undefined : onSave}
      />
      {error && <div className={df.errorBanner}>{error}</div>}
      {loading && <div className={df.loading}>Đang tải...</div>}
      {!missing && !loading && (
        <>
          <section className={df.section}>
            <h2 className={df.sectionTitle}>Chứng từ</h2>
            <div className={df.row4}>
              <Select label="Loại giao dịch" disabled={readOnly} data-testid="ct-pxf-field-maGd" value={form.maGd} options={[{ value: '1', label: 'Hàng trả lại' }]} onChange={event => setField('maGd', event.target.value)} />
              <Select label="Trạng thái" disabled={readOnly} data-testid="ct-pxf-field-maPost" value={form.maPost} options={[{ value: '3', label: 'Lập chứng từ' }, { value: '9', label: 'Hạch toán sổ cái' }]} onChange={event => setField('maPost', event.target.value)} />
              <div><label className={df.label}>Quyền số</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pxf-field-maQuyen" value={form.maQuyen} onChange={event => setField('maQuyen', event.target.value)} /></div>
              <div><label className={df.label}>Ngày C.từ</label><Input disabled={readOnly} type="date" data-testid="ct-pxf-field-ngayCt" value={form.ngayCt} onChange={event => setField('ngayCt', event.target.value)} /></div>
              <div><label className={df.label}>Ngày lập</label><Input disabled={readOnly} type="date" data-testid="ct-pxf-field-ngayLct" value={form.ngayLct} onChange={event => setField('ngayLct', event.target.value)} /></div>
              <div><label className={df.label}>Số C.từ</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pxf-field-soCt" value={form.soCt} onChange={event => setField('soCt', event.target.value)} /></div>
              <div><label className={df.label}>Số seri</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pxf-field-soSeri" value={form.soSeri} onChange={event => setField('soSeri', event.target.value)} /></div>
              <div><label className={df.label}>Số lô</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pxf-field-soLo" value={form.soLo} onChange={event => setField('soLo', event.target.value)} /></div>
              <div><label className={df.label}>Ngày lô</label><Input disabled={readOnly} type="date" data-testid="ct-pxf-field-ngayLo" value={form.ngayLo} onChange={event => setField('ngayLo', event.target.value)} /></div>
              <div><label className={df.label}>Mẫu hóa đơn</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pxf-field-mauHd" value={form.mauHd} onChange={event => setField('mauHd', event.target.value)} /></div>
              <div><label className={df.label}>Số mẫu</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pxf-field-mauSo" value={form.mauSo} onChange={event => setField('mauSo', event.target.value)} /></div>
              <div><label className={df.label}>Mẫu báo cáo</label><Input disabled={readOnly} maxLength={10} data-testid="ct-pxf-field-mauBc" value={form.mauBc} onChange={event => setField('mauBc', event.target.value)} /></div>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Đối tượng</h2>
            <div className={df.row4}>
              <div><label className={df.label}>Đối tượng</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pxf-field-maKh" value={form.maKh} onChange={event => setField('maKh', event.target.value)} onBlur={() => { void onBlurCustomer(); }} /></div>
              <div><label className={df.label}>Tên đối tượng</label><Input disabled data-testid="ct-pxf-field-tenKh" value={form.tenKh} onChange={() => undefined} /></div>
              <div><label className={df.label}>Người giao</label><Input disabled={readOnly} maxLength={200} data-testid="ct-pxf-field-ongBa" value={form.ongBa} onChange={event => setField('ongBa', event.target.value)} /></div>
              <div><label className={df.label}>Địa chỉ</label><Input disabled={readOnly} maxLength={200} data-testid="ct-pxf-field-diaChi" value={form.diaChi} onChange={event => setField('diaChi', event.target.value)} /></div>
              <div><label className={df.label}>Mã số thuế</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pxf-field-maSoThue" value={form.maSoThue} onChange={event => setField('maSoThue', event.target.value)} /></div>
              <div className={df.spanCol2}><label className={df.label}>Diễn giải</label><Input disabled={readOnly} maxLength={200} data-testid="ct-pxf-field-dienGiai" value={form.dienGiai} onChange={event => setField('dienGiai', event.target.value)} /></div>
              <div><label className={df.label}>Tên khách VAT</label><Input disabled={readOnly} maxLength={200} data-testid="ct-pxf-field-tenKhVat" value={form.tenKhVat} onChange={event => setField('tenKhVat', event.target.value)} /></div>
              <div><label className={df.label}>Địa chỉ VAT</label><Input disabled={readOnly} maxLength={200} data-testid="ct-pxf-field-diaChiVat" value={form.diaChiVat} onChange={event => setField('diaChiVat', event.target.value)} /></div>
              <div><label className={df.label}>Tên hàng thuế</label><Input disabled={readOnly} maxLength={200} data-testid="ct-pxf-field-tenVtThue" value={form.tenVtThue} onChange={event => setField('tenVtThue', event.target.value)} /></div>
              <div><label className={df.label}>Bộ phận</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pxf-field-maBpH" value={form.maBpH} onChange={event => touch({ ...form, maBpH: event.target.value, tenBpH: '' })} /></div>
              <div><label className={df.label}>Tên bộ phận</label><Input disabled data-testid="ct-pxf-field-tenBpH" value={form.tenBpH} onChange={() => undefined} /></div>
              <div><label className={df.label}>Hồ sơ</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pxf-field-maHsH" value={form.maHsH} onChange={event => touch({ ...form, maHsH: event.target.value, tenHsH: '' })} /></div>
              <div><label className={df.label}>Tên hồ sơ</label><Input disabled data-testid="ct-pxf-field-tenHsH" value={form.tenHsH} onChange={() => undefined} /></div>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Tài khoản và tiền tệ</h2>
            <div className={df.row4}>
              <div><label className={df.label}>Tài khoản nợ</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pxf-field-maNx" value={form.maNx} onChange={event => setField('maNx', event.target.value)} onBlur={() => { void onBlurAccount(); }} /></div>
              <div><label className={df.label}>Tên tài khoản nợ</label><Input disabled data-testid="ct-pxf-field-tenNx" value={form.tenNx} onChange={() => undefined} /></div>
              <Checkbox label="Giá đích danh" disabled={readOnly} data-testid="ct-pxf-field-pxGiaDd" checked={form.pxGiaDd} onChange={event => setField('pxGiaDd', event.target.checked)} />
              <div><label className={df.label}>Ngoại tệ</label><Input disabled={readOnly} maxLength={3} data-testid="ct-pxf-field-maNt" value={form.maNt} onChange={event => setField('maNt', event.target.value)} /></div>
              <div><label className={df.label}>Tỷ giá</label><Input disabled={readOnly} inputMode="decimal" data-testid="ct-pxf-field-tyGia" value={form.tyGia} onChange={event => setField('tyGia', event.target.value)} /></div>
              <div><label className={df.label}>Mã thuế</label><Input disabled={readOnly} maxLength={10} data-testid="ct-pxf-field-maThue" value={form.maThue} onChange={event => setField('maThue', event.target.value)} /></div>
              <div><label className={df.label}>Thuế suất</label><Input disabled={readOnly} inputMode="decimal" data-testid="ct-pxf-field-thueSuat" value={form.thueSuat} onChange={event => setField('thueSuat', event.target.value)} /></div>
              <div><label className={df.label}>Tài khoản thuế nợ</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pxf-field-tkThueNo" value={form.tkThueNo} onChange={event => setField('tkThueNo', event.target.value)} /></div>
              <div><label className={df.label}>Tài khoản thuế có</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pxf-field-tkThueCo" value={form.tkThueCo} onChange={event => setField('tkThueCo', event.target.value)} /></div>
              <div><label className={df.label}>Hạn thanh toán</label><Input disabled={readOnly} inputMode="decimal" data-testid="ct-pxf-field-hanTt" value={form.hanTt} onChange={event => setField('hanTt', event.target.value)} /></div>
              <div><label className={df.label}>Lệnh số</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pxf-field-lenhSo" value={form.lenhSo} onChange={event => setField('lenhSo', event.target.value)} /></div>
              <div><label className={df.label}>Lệnh PO</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pxf-field-lenhPo" value={form.lenhPo} onChange={event => setField('lenhPo', event.target.value)} /></div>
              <div><label className={df.label}>Lệnh RO</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pxf-field-lenhRo" value={form.lenhRo} onChange={event => setField('lenhRo', event.target.value)} /></div>
              <div><label className={df.label}>Lệnh VT</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pxf-field-lenhVt" value={form.lenhVt} onChange={event => setField('lenhVt', event.target.value)} /></div>
              <div className={df.spanCol2}><label className={df.label}>Ghi chú</label><Input disabled={readOnly} maxLength={200} data-testid="ct-pxf-field-ghiChu" value={form.ghiChu} onChange={event => setField('ghiChu', event.target.value)} /></div>
              <Checkbox label="Sửa thuế" disabled={readOnly} data-testid="ct-pxf-field-suaThue" checked={form.suaThue} onChange={event => setField('suaThue', event.target.checked)} />
              <Checkbox label="E thuế" disabled={readOnly} data-testid="ct-pxf-field-eThue" checked={form.eThue} onChange={event => setField('eThue', event.target.checked)} />
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Tổng</h2>
            <div className={df.row4}>
              <div><label className={df.label}>Tổng số lượng</label><Input disabled data-testid="ct-pxf-field-tSoLuong" value={showMoney(form.tSoLuong)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Tổng số lượng 1</label><Input disabled data-testid="ct-pxf-field-tSoluong1" value={showMoney(form.tSoluong1)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Tổng Ps NT</label><Input disabled data-testid="ct-pxf-field-tTienNt" value={showMoney(form.tTienNt)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Tổng Phát sinh</label><Input disabled data-testid="ct-pxf-field-tTien" value={showMoney(form.tTien)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Tiền thuế NT</label><Input disabled data-testid="ct-pxf-field-tThueNt" value={showMoney(form.tThueNt)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Tiền thuế</label><Input disabled data-testid="ct-pxf-field-tThue" value={showMoney(form.tThue)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Thanh toán NT</label><Input disabled data-testid="ct-pxf-field-tTtNt" value={showMoney(form.tTtNt)} onChange={() => undefined} /></div>
              <div><label className={df.label}>Thanh toán</label><Input disabled data-testid="ct-pxf-field-tTt" value={showMoney(form.tTt)} onChange={() => undefined} /></div>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Dòng hàng</h2>
            {!readOnly && (
              <div>
                <Button className={df.btnAddLine} data-testid="ct-pxf-line-add-btn" onClick={() => { touch({ ...form, lines: [...form.lines, emptyLine()] }); setSelectedLine(form.lines.length); }}>Thêm dòng</Button>
                <Button className={df.btnDeleteLine} data-testid="ct-pxf-line-remove-btn" disabled={selectedLine < 0} onClick={() => { const lines = form.lines.filter((_, i) => i !== selectedLine); touch({ ...form, lines }); setSelectedLine(-1); }}>Xóa dòng</Button>
              </div>
            )}
            <div className={df.tableWrapper}>
              <table className={df.linesTable} data-testid="ct-pxf-line-grid">
                <thead>
                  <tr>
                    <th>Hàng hoá</th><th>Tên hàng hoá</th><th>ĐVT</th><th>Vị trí</th><th>Kho</th>
                    <th>Tồn</th><th>Số lượng</th><th>Giá</th><th>Nguyên tệ</th><th>TK Có</th>
                    <th>Giá VNĐ</th><th>Tiền VNĐ</th>
                    <th>V.Việc</th><th>Hợp đồng</th><th>khoản mục</th><th>Trung tâm lợi nhuận</th><th>Trung tâm chi phí</th><th>Phòng ban</th>
                  </tr>
                </thead>
                <tbody>
                  {form.lines.map((line, i) => {
                    const selected = i === selectedLine;
                    return (
                      <tr key={`${line.sttRec0}-${i}`} aria-selected={selected} style={selected ? { background: 'var(--ds-color-primary-bg, rgba(13, 110, 253, 0.08))' } : undefined} onClick={() => setSelectedLine(i)}>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pxf-line-${i}-maVt`} value={line.maVt} onChange={event => setLine(i, { maVt: event.target.value })} onBlur={() => { void onBlurMaterial(i); }} /></td>
                        <td><Input disabled data-testid={`ct-pxf-line-${i}-tenVt`} value={line.tenVt} onChange={() => undefined} /></td>
                        <td><Input disabled data-testid={`ct-pxf-line-${i}-dvt`} value={line.dvt} onChange={() => undefined} /></td>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pxf-line-${i}-maVitri`} value={line.maVitri} onChange={event => setLine(i, { maVitri: event.target.value })} /></td>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pxf-line-${i}-maKhoI`} value={line.maKhoI} onChange={event => setLine(i, { maKhoI: event.target.value })} /></td>
                        <td><Input disabled inputMode="decimal" data-testid={`ct-pxf-line-${i}-ton13`} value={line.ton13} onChange={() => undefined} /></td>
                        <td><Input disabled={readOnly} inputMode="decimal" data-testid={`ct-pxf-line-${i}-soLuong`} value={line.soLuong} onChange={event => setLine(i, { soLuong: event.target.value })} /></td>
                        <td><Input disabled={readOnly} inputMode="decimal" data-testid={`ct-pxf-line-${i}-giaNt`} value={line.giaNt} onChange={event => setLine(i, { giaNt: event.target.value })} /></td>
                        <td><Input disabled={readOnly} inputMode="decimal" data-testid={`ct-pxf-line-${i}-tienNt`} value={line.tienNt} onChange={event => setLine(i, { tienNt: event.target.value })} /></td>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pxf-line-${i}-tkVt`} value={line.tkVt} onChange={event => setLine(i, { tkVt: event.target.value })} /></td>
                        <td><Input disabled inputMode="decimal" data-testid={`ct-pxf-line-${i}-gia`} value={line.gia} onChange={() => undefined} /></td>
                        <td><Input disabled inputMode="decimal" data-testid={`ct-pxf-line-${i}-tien`} value={line.tien} onChange={() => undefined} /></td>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pxf-line-${i}-maVvI`} value={line.maVvI} onChange={event => setLine(i, { maVvI: event.target.value })} /></td>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pxf-line-${i}-maHdI`} value={line.maHdI} onChange={event => setLine(i, { maHdI: event.target.value })} /></td>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pxf-line-${i}-maPhiI`} value={line.maPhiI} onChange={event => setLine(i, { maPhiI: event.target.value })} /></td>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pxf-line-${i}-maTtlnI`} value={line.maTtlnI} onChange={event => setLine(i, { maTtlnI: event.target.value })} /></td>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pxf-line-${i}-maTtcpI`} value={line.maTtcpI} onChange={event => setLine(i, { maTtcpI: event.target.value })} /></td>
                        <td><Input disabled={readOnly} maxLength={30} data-testid={`ct-pxf-line-${i}-maBpI`} value={line.maBpI} onChange={event => setLine(i, { maBpI: event.target.value })} /></td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </section>

          <div className={df.footer}>
            <span className={df.totalLabel}>Thanh toán</span>
            <span className={df.totalValue}>{showMoney(form.tTt)}</span>
          </div>
        </>
      )}
      <LeaveConfirmModal {...leaveConfirmModalProps} />
    </div>
  );
};

export default PxfFormPage;
